package net.officefloor.hq.app.setting;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Sets the user name's role on the sheet, replacing any it had. */
public class ApplyRole {
    public void apply(@PathVariable("sheetId") String sheetId, @Val RoleInput input, UserRoleRepository repository,
            Out<UserRole> roleOut) {
        String id = sheetId.trim();
        UserRole role = repository.findBySheetIdAndUser(id, input.user()).orElseGet(() -> new UserRole(id, input.user()));
        role.setRole(input.role());
        roleOut.set(role);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.HttpHeaderParameter;

/** Records ROLE_SET once the role is saved; the signed-in user arrives as X-User. */
public class AuditRoleSet {
    public void audit(@Val UserRole role, @HttpHeaderParameter("X-User") String user, Audit audit) {
        audit.record("ROLE_SET sheet=" + role.getSheetId() + " by=" + (user == null ? "" : user.trim())
                + " user=" + role.getUser() + " role=" + role.getRole());
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidSetting {
    public void handle(@Parameter InvalidSettingException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.setting;

/** A setting or role to save is not valid; nothing is changed. */
public class InvalidSettingException extends Exception {
    public InvalidSettingException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithRole {
    public void respond(@Val UserRole role, ObjectResponse<RoleResponse> response) {
        response.send(RoleResponse.from(role));
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** The roles assigned on the sheet, by user name. */
public class RespondWithRoles {
    public void respond(@PathVariable("sheetId") String sheetId, UserRoleRepository repository,
            ObjectResponse<RolesResponse> response) {
        response.send(RolesResponse.from(repository.findBySheetIdOrderByUser(sheetId.trim())));
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** The sheet's settings. */
public class RespondWithSettings {
    public void respond(@PathVariable("sheetId") String sheetId, SettingRepository repository,
