import { useQuery } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { useCurrentSheet, useSheetToday } from '../session/session';
import { hundredths } from '../rates/rates';

// A sheet's settings: the clerk limit (two decimals; null: no limit). And the role each user name has
// on the sheet: clerk (any name not given one) or steward. A clerk settles only a claim whose due is
// at or below the clerk limit; a steward settles any. The floor (two decimals, 1.00 until set): a
// claim's live due is at least it. The terms (whole days, 14 until set): a claim is due by its date plus them.
// The late percent (two decimals, 0.00 until set): an overdue claim's live due gains it of its floored due for
// every full 30 days it is overdue. The policy date (null: the sheet's today): a claim dated before it rounds
// its live figures half up, one dated on or after it half to even. The period numbering date (null: off): while
// the sheet's today is on or after it, a claim opened is numbered within its period (<period name>-<n>, X-<n> in none).
export type Settings = { clerkLimit: string | null; floor: string; terms: string; latePct: string; policyDate: string | null; periodNumberingFrom: string | null };
export type SettingsInput = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string; periodNumberingFrom: string };
export type Role = 'clerk' | 'steward';
export type UserRole = { user: string; role: Role };

/** Empty (unchanged), or a whole number of days, 0 or more. */
export const TERMS = /^(\d{1,4})?$/;

export const ROLES: Role[] = ['clerk', 'steward'];

/** Empty (the sheet's today), or a date. */
export const POLICY_DATE = /^(\d{4}-\d{2}-\d{2})?$/;

/** Empty (no limit), or 0.00 or more with up to two decimals. */
export const LIMIT = /^(\d{1,12}(\.\d{1,2})?)?$/;

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}`;
export const settingsKey = (sheet: string) => ['sheet', sheet, 'settings'] as const;
export const rolesKey = (sheet: string) => ['sheet', sheet, 'roles'] as const;

/** The active sheet's settings. */
export function useSettings() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: settingsKey(sheet ?? ''),
    queryFn: () => getJson<Settings>(`${base(sheet!)}/settings`),
    enabled: !!sheet,
  });
}

/** The roles assigned on the active sheet, by user name. */
export function useRoles() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: rolesKey(sheet ?? ''),
    queryFn: () => getJson<{ roles: UserRole[] }>(`${base(sheet!)}/roles`).then((r) => r.roles),
    enabled: !!sheet,
  });
}

export const saveSettings = (sheet: string, user: string, settings: SettingsInput) =>
  postJson<Settings>(`${base(sheet)}/settings`, settings, user);

export const setRole = (sheet: string, user: string, input: { user: string; role: string }) =>
  postJson<UserRole>(`${base(sheet)}/roles`, input, user);

/** The floor in force before the sheet's settings load or any is set. */
export const DEFAULT_FLOOR = '1.00';

/** The active sheet's floor in cents: a claim's live due is at least it. */
export function useFloor(): bigint {
  return hundredths(useSettings().data?.floor ?? DEFAULT_FLOOR);
}

/** The terms in force before the sheet's settings load or any is set. */
export const DEFAULT_TERMS = '14';

/** The active sheet's terms in days: a claim is due by its date plus them. */
export function useTerms(): number {
  return Number(useSettings().data?.terms ?? DEFAULT_TERMS);
}

/** Whether the user is a steward on the active sheet (a name with no role is a clerk). */
export function useIsSteward() {
  const roles = useRoles().data ?? [];
  return (user: string) => roles.find((r) => r.user === user.trim())?.role === 'steward';
}

/** The late percent in force before the sheet's settings load or any is set. */
export const DEFAULT_LATE_PCT = '0.00';

/** The active sheet's late percent in hundredths of a percent. */
export function useLatePct(): bigint {
  return hundredths(useSettings().data?.latePct ?? DEFAULT_LATE_PCT);
}

/** Whether a claim dated on this date (yyyy-mm-dd) rounds its live figures half up: it is dated before the
 *  sheet's policy date (its today when none is set); otherwise it rounds half to even. */
export function useRoundsHalfUp() {
  const policy = useSettings().data?.policyDate ?? null;
  const today = useSheetToday();
  return (date: string) => {
    const on = policy ?? today;
    return on !== undefined && date < on;
  };
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import type { SettingsInput } from './settings';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { LIMIT, POLICY_DATE, ROLES, TERMS, rolesKey, saveSettings, setRole, settingsKey, useRoles, useSettings } from './settings';

// The sheet's settings: the clerk limit (blank: no limit), the floor, the terms and the late percent (blank: unchanged), and the
// policy date (blank: the sheet's today) and the period numbering date (blank: off), each with
// the one in force shown beside it.
function SettingsPanel() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const settings = useSettings().data;
  const [limit, setLimit] = useState('');
  const [floor, setFloor] = useState('');
  const [terms, setTerms] = useState('');
  const [latePct, setLatePct] = useState('');
  const [policyDate, setPolicyDate] = useState('');
  const [numberingFrom, setNumberingFrom] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (input: SettingsInput) => saveSettings(sheet!, user, input),
    onSuccess: async (saved) => {
      queryClient.setQueryData(settingsKey(sheet!), saved);
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheet!) });
    },
    onError: () => setError('The settings could not be saved: the clerk limit must be blank or 0.00 or more, and the floor blank or 0.00 or more, with up to two decimals, the terms blank or a whole number of days, the late percent blank or 0.00 or more with up to two decimals, the policy date blank or a date, and the period numbering date blank or a date.'),
  });

  if (!sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const value = limit.trim();
    if (!LIMIT.test(value)) {
      setError('The clerk limit must be blank or 0.00 or more, with up to two decimals.');
      return;
    }
    const floorValue = floor.trim();
    if (!LIMIT.test(floorValue)) {
      setError('The floor must be blank or 0.00 or more, with up to two decimals.');
      return;
    }
    const termsValue = terms.trim();
    if (!TERMS.test(termsValue)) {
      setError('The terms must be blank or a whole number of days, 0 or more.');
      return;
    }
    const lateValue = latePct.trim();
    if (!LIMIT.test(lateValue)) {
      setError('The late percent must be blank or 0.00 or more, with up to two decimals.');
      return;
    }
    const policyValue = policyDate.trim();
    if (!POLICY_DATE.test(policyValue)) {
      setError('The policy date must be blank or a date (yyyy-mm-dd).');
      return;
    }
    const numberingValue = numberingFrom.trim();
    if (!POLICY_DATE.test(numberingValue)) {
      setError('The period numbering date must be blank or a date (yyyy-mm-dd).');
      return;
    }
    once(() =>
      save.mutateAsync({
        clerkLimit: value,
        floor: floorValue,
        terms: termsValue,
        latePct: lateValue,
        policyDate: policyValue,
        periodNumberingFrom: numberingValue,
      }),
    );
  };

  return (
    <section data-testid="settings">
      <h2>Settings</h2>
      <form data-testid="settings-form" onSubmit={submit}>
        <label>
          Clerk limit{' '}
          <input
            data-testid="setting-clerk-limit"
            placeholder="No limit"
            inputMode="decimal"
            value={limit}
            onChange={(e) => {
              setLimit(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <span>
          now <strong data-testid="setting-clerk-limit-current">{settings?.clerkLimit ?? ''}</strong>
        </span>{' '}
        <label>
          Floor{' '}
          <input
            data-testid="setting-floor"
            placeholder="Unchanged"
            inputMode="decimal"
            value={floor}
            onChange={(e) => {
              setFloor(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <span>
          now <strong data-testid="setting-floor-current">{settings?.floor ?? ''}</strong>
        </span>{' '}
        <label>
          Terms (days){' '}
          <input
            data-testid="setting-terms"
            placeholder="Unchanged"
            inputMode="numeric"
            value={terms}
            onChange={(e) => {
              setTerms(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <span>
          now <strong data-testid="setting-terms-current">{settings?.terms ?? ''}</strong>
        </span>{' '}
        <label>
          Late percent{' '}
          <input
            data-testid="setting-late-pct"
            placeholder="Unchanged"
            inputMode="decimal"
            value={latePct}
            onChange={(e) => {
              setLatePct(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <span>
          now <strong data-testid="setting-late-pct-current">{settings?.latePct ?? ''}</strong>
        </span>{' '}
        <label>
          Policy date{' '}
          <input
            data-testid="setting-policy-date"
            placeholder="Today"
            value={policyDate}
            onChange={(e) => {
              setPolicyDate(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <span>
          now <strong data-testid="setting-policy-date-current">{settings?.policyDate ?? ''}</strong>
        </span>{' '}
        <label>
          Period numbering from{' '}
          <input
            data-testid="setting-period-numbering-from"
            placeholder="Off"
            value={numberingFrom}
            onChange={(e) => {
              setNumberingFrom(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <span>
          now <strong data-testid="setting-period-numbering-from-current">{settings?.periodNumberingFrom ?? ''}</strong>
        </span>{' '}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {error && <span data-testid="settings-error">{error}</span>}
      </form>
    </section>
  );
}

// The roles on the sheet: a form that gives a user name a role (clerk or steward), replacing any it had,
// and each name given one. A name not listed is a clerk.
function Roles() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const roles = useRoles().data ?? [];
  const [form, setForm] = useState({ user: '', role: '' });
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (input: { user: string; role: string }) => setRole(sheet!, user, input),
    onSuccess: async () => {
      setForm({ user: '', role: '' });
      await queryClient.invalidateQueries({ queryKey: rolesKey(sheet!) });
    },
    onError: () => setError('The role could not be set: the user name must not be empty and the role must be clerk or steward.'),
  });

  if (!sheet) return null;

  const change = (patch: Partial<typeof form>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const name = form.user.trim();
    const role = form.role.trim();
    if (!name) {
      setError('Type a user name.');
      return;
    }
    if (!(ROLES as string[]).includes(role)) {
      setError(`The role must be ${ROLES.join(' or ')}.`);
      return;
    }
    once(() => save.mutateAsync({ user: name, role }));
  };

  return (
    <section data-testid="roles">
      <h2>Roles</h2>
      <form data-testid="role-form" onSubmit={submit}>
        <input data-testid="role-form-user" placeholder="User name" value={form.user} onChange={(e) => change({ user: e.target.value })} />
        <input
          data-testid="role-form-role"
          placeholder="clerk or steward"
          list="role-options"
          value={form.role}
          onChange={(e) => change({ role: e.target.value })}
        />
        <datalist id="role-options">
          {ROLES.map((r) => (
            <option key={r} value={r} />
          ))}
        </datalist>
        <button type="submit" data-testid="role-form-submit" disabled={save.isPending}>
          Set role
        </button>
        {error && <span data-testid="role-form-error">{error}</span>}
      </form>
      <table data-testid="role-list">
        <thead>
          <tr>
            <th>User</th>
            <th>Role</th>
          </tr>
        </thead>
        <tbody>
          {roles.map((r) => (
            <tr key={r.user} data-testid={`role-row-${r.user}`}>
              <td data-testid="role-user">{r.user}</td>
              <td data-testid="role-value">{r.role}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contributions = [
  HomeMain.fill({ order: 7, Component: SettingsPanel }),
  HomeMain.fill({ order: 8, Component: Roles }),
];
import { useSyncExternalStore } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson, putJson } from '../../api/http';
import { useCurrentSheet, useSheetToday } from '../session/session';
import { usePeople } from '../people/people';
import { useFloor, useLatePct, useRoundsHalfUp, useTerms } from '../settings/settings';
import { claimDueCents } from '../rates/rates';

// Amounts travel as strings with two decimals ("13.50"); sums are added up in whole cents so no
// floating-point error shows.
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  /** Given when opened, the next on the sheet; null for a draft; a voided claim keeps it. */
  number: number | null;
  /** Fixed when settled (two decimals); null while live, or when no rate applied at settling. */
  settledDue: string | null;
  /** The user who opened it; null for a draft. */
  openedBy: string | null;
  /** For a correction (a negative amount), the number of the SETTLED claim it corrects; null otherwise. */
  corrects: number | null;
  /** Given instead of a number when opened while period numbering is on: <period name>-<n>, or X-<n> in no period. */
  periodNumber: string | null };
export type ClaimInput = { amount: string; date: string; note: string; corrects: string };

/** A number with up to two decimals; negative only for a correction. */
export const AMOUNT = /^-?\d+(\.\d{1,2})?$/;

/** A claim number. */
export const NUMBER = /^\d{1,9}$/;

/** Whether an amount is negative, which makes its claim a correction. */
export const isCorrection = (amount: string) => /^-/.test(amount.trim()) && /[1-9]/.test(amount);

/** A correction must name, by number, a SETTLED claim of the same person; any other claim names none. */
export function correctionError(claims: Claim[], personId: number, amount: string, corrects: string): string | undefined {
  const named = corrects.trim();
  if (named !== '' && !NUMBER.test(named)) return 'The claim corrected must be given by its number.';
  if (!isCorrection(amount)) {
    return named === '' ? undefined : 'Only a correction (a negative amount) names a claim it corrects.';
  }
  if (named === '') return 'A negative amount is a correction: name the settled claim it corrects.';
  const target = claims.find((c) => c.number === Number(named));
  if (!target || target.personId !== personId || target.status !== 'SETTLED') {
    return `A correction must name a settled claim of the same person; claim ${named} is not one.`;
  }
  return undefined;
}

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}`;
export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** The active sheet's claims, newest first. */
export function useClaims() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: claimsKey(sheet ?? ''),
    queryFn: () => getJson<{ claims: Claim[] }>(`${base(sheet!)}/claims`).then((r) => r.claims),
    enabled: !!sheet,
  });
}
  const n = Number(whole) * 100 + Number((frac + '00').slice(0, 2));
  return negative ? -n : n;
};

/** The amounts of the claims that count (by `counted`, from `useCounts`) added up, shown with two decimals. */
export function total(claims: Claim[], counted: (claim: Claim) => boolean): string {
  const sum = claims.filter(counted).reduce((n, c) => n + cents(c.amount), 0);
  const abs = Math.abs(sum);
  return `${sum < 0 ? '-' : ''}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}

/** A date (yyyy-mm-dd) plus a number of days, as yyyy-mm-dd. */
export function addDays(date: string, days: number): string {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
}

/** A claim's due-by: its date plus the sheet's terms in force (days). */
export function useDueBy() {
  const terms = useTerms();
  return (claim: Claim) => addDays(claim.date, terms);
}

/** Whether a claim is overdue: it is live (OPEN or PENDING) and its due-by is before the sheet's today. */
export function useOverdue() {
  const dueBy = useDueBy();
  const today = useSheetToday();
  return (claim: Claim) => live(claim) && today !== undefined && dueBy(claim) < today;
}

/** Whole days from one date (yyyy-mm-dd) to another. */
export function daysBetween(from: string, to: string): number {
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86400000);
}

/** A claim's due in cents (see `claimDueCents`) at a rate, with the sheet's floor and, while it is overdue,
 *  the late percent for each full 30 days past its due-by, rounded by the sheet's policy date. */
export function useClaimDue() {
  const halfUp = useRoundsHalfUp();
  const floor = useFloor();
  const latePct = useLatePct();
  const dueBy = useDueBy();
  const overdue = useOverdue();
  const today = useSheetToday();
  return (claim: Claim, rate: string | undefined) => {
    const spans = overdue(claim) && today !== undefined ? BigInt(Math.floor(daysBetween(dueBy(claim), today) / 30)) : 0n;
    return claimDueCents(claim, rate, floor, latePct, spans, halfUp(claim.date));
  };
}

