sub(p, "import { LIMIT,", "import { GRADES } from '../people/people';\nimport { LIMIT,")
sub(p, "  const [latePct, setLatePct] = useState('');", "  const [gradeTerms, setGradeTerms] = useState<Record<string, string>>({});\n  const [latePct, setLatePct] = useState('');")
sub(p, "    const lateValue = latePct.trim();", """    const gradeValues: Record<string, string> = {};
    for (const g of GRADES) {
      const v = (gradeTerms[g] ?? '').trim();
      if (!TERMS.test(v)) {
        setError(`The terms of grade ${g} must be blank or a whole number of days, 0 or more.`);
        return;
      }
      if (v) gradeValues[g] = v;
    }
    const lateValue = latePct.trim();""")
sub(p, "        latePct: lateValue,", "        latePct: lateValue,\n        gradeTerms: gradeValues,")
sub(p, """          now <strong data-testid="setting-terms-current">{settings?.terms ?? ''}</strong>
