              <input
                data-testid={`setting-terms-${g}`}
                placeholder="Unchanged"
                inputMode="numeric"
                value={gradeTerms[g] ?? ''}
                onChange={(e) => {
                  setGradeTerms((t) => ({ ...t, [g]: e.target.value }));
                  setError('');
                }}
              />
            </label>{' '}
            <span>
              now <strong data-testid={`setting-terms-${g}-current`}>{settings?.gradeTerms?.[g] ?? ''}</strong>
            </span>{' '}
          </span>
        ))}
""")
sub(p, "the terms and the late percent (blank: unchanged)", "the terms, each grade's own terms (none: the sheet's) and the late percent (blank: unchanged)")
